package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
import kotlin.random.Random
class VideoClipReplacementTest {
 private fun original()=VideoSegment(1000,5000,speed=1.5f,volume=.4f,title="Preserved",fadeEdges=true,grade=VideoGrade(exposure=.5f),layout=VideoLayout(rotation=90,mirrorX=true),titleStyle=VideoTitleStyle(size=.08f),audioFade=true,captions=listOf(VideoCaption(1500,2500,"Old source speech")),captionSourceUri="content://synthetic/subtitles",motion=VideoMotion(enabled=true,endZoom=1.5f,anchorStartMs=0,anchorEndMs=6000))
 private val catalog=linkedMapOf("primary" to 10000L,"other" to 15000L,"short" to 3999L)
 @Test fun targetsExcludeCurrentAndShortSourcesButAllowExactFit(){val c=listOf(original());val r=VideoClipReplacement.targets(c,0,catalog+mapOf("exact" to 4000L));assertEquals(listOf("other","exact"),r.map{it.id});assertEquals(listOf(11000L,0L),r.map{it.latestStartMs})}
 @Test fun differentSourceKeepsAllStaticPropertiesAndClearsOnlySourceAnnotations(){val c=original();val r=VideoClipReplacement.propose(listOf(c),0,catalog,"other",7000).single();assertEquals(c.copy(sourceId="other",startMs=7000,endMs=11000,captions=emptyList(),captionSourceUri=null,motion=VideoMotion()),r);assertEquals(c.durationUs,r.durationUs);assertEquals(1,c.captions.size);assertNotNull(c.captionSourceUri);assertNotEquals(VideoMotion(),c.motion)}
 @Test fun wholeTimelineAndNeighborsKeepExactDurationAndIdentity(){val a=VideoSegment(0,1000);val b=VideoSegment(6000,9000,speed=2f);val c=listOf(a,original(),b);val r=VideoClipReplacement.propose(c,1,catalog,"other",0);assertSame(a,r[0]);assertSame(b,r[2]);assertEquals(VideoPlaybackTime.durationUs(c),VideoPlaybackTime.durationUs(r));assertEquals(c[1].speed,r[1].speed)}
 @Test fun permitsFirstAndLastLegalWindowsButRejectsOutsideBounds(){for(start in listOf(0L,11000L)){val r=VideoClipReplacement.propose(listOf(original()),0,catalog,"other",start).single();assertEquals(start,r.startMs);assertEquals(start+4000,r.endMs)};for(start in listOf(-1L,11001L,Long.MAX_VALUE))assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.propose(listOf(original()),0,catalog,"other",start)}}
 @Test fun sameUnknownAndInsufficientSourcesAreRefused(){for(id in listOf("primary","unknown","short"))assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.propose(listOf(original()),0,catalog,id,0)}}
 @Test fun invalidIndexCountsCatalogAndChangedOriginalBoundsFail(){for(index in listOf(-1,1))assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.targets(listOf(original()),index,catalog)};for(map in listOf(emptyMap(),mapOf("primary" to 4999L),catalog+mapOf("bad id" to 5000L),catalog+mapOf("__private" to 5000L),catalog+mapOf("big" to Int.MAX_VALUE.toLong()+1),catalog+mapOf("zero" to 0L)))assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.targets(listOf(original()),0,map)};assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.targets(emptyList(),0,catalog)};assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.targets(List(1001){original()},0,catalog)};assertThrows(IllegalArgumentException::class.java){VideoClipReplacement.targets(listOf(original()),0,(0..32).associate{"id$it" to 10000L}+catalog)}}
 @Test fun noCaptionOrDefaultMotionInputsStillReplaceWithoutInventingAnnotations(){val c=VideoSegment(0,1000);val r=VideoClipReplacement.propose(listOf(c),0,catalog,"other",1000).single();assertTrue(r.captions.isEmpty());assertNull(r.captionSourceUri);assertEquals(VideoMotion(),r.motion)}
 @Test fun replacementCanReturnToRegisteredPrimaryFromImportedSource(){val c=original().copy(sourceId="other");val r=VideoClipReplacement.propose(listOf(c),0,catalog,"primary",6000).single();assertEquals("primary",r.sourceId);assertEquals(10000L,r.endMs)}
 @Test fun randomOffsetsAndAllSpeedsPreserveExactPlaybackSpan(){val rng=Random(128);for(speed in listOf(.5f,1f,1.5f,2f))repeat(75){val start=rng.nextLong(0,5000);val span=rng.nextLong(1,5000);val clip=VideoSegment(start,start+span,speed=speed);val latest=15000-span;val at=rng.nextLong(0,latest+1);val result=VideoClipReplacement.propose(listOf(clip),0,catalog,"other",at).single();assertEquals(clip.durationUs,result.durationUs);assertEquals(span,result.endMs-result.startMs);assertEquals(at,result.startMs);assertTrue(result.endMs<=15000)}}
 @Test fun actualProjectApprovalOneUndoRestoresSourceCaptionsMotionAndProtectedDocuments(){val c=original();val p=VideoEditProject(10000);val music=VideoSoundtrack("content://synthetic/music",20000,loop=false);p.restore(listOf(c),catalog.filterKeys{it!="primary"},music);val next=VideoClipReplacement.propose(p.segments,0,catalog,"other",0,music);val request=VideoBatchReview(p.segments,music);val stage=Any();request.open(stage);request.propose(stage,next);assertTrue(request.apply(stage,p){});assertEquals("other",p.segments.single().sourceId);assertEquals(music,p.soundtrack);assertTrue("content://synthetic/subtitles" in p.captionSourceUris());assertTrue(p.undo());assertEquals(listOf(c),p.segments);assertEquals(music,p.soundtrack);assertFalse(p.canUndo);assertFalse(request.apply(stage,p){});assertTrue(p.redo());assertEquals(next,p.segments)}
 @Test fun replacementProjectCodecRoundTripKeepsNewBindingAndExistingSourceCatalog(){val clip=VideoClipReplacement.propose(listOf(original()),0,catalog,"other",5000).single();val draft=VideoDraft(10000,listOf(clip),0,5000,5000,9000,listOf(VideoSource("other","content://synthetic/other",15000)));assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),10000))}
 @Test fun staleForeignPausedOrDismissedRequestCannotApply(){for(mode in 0..3){val c=original();val p=VideoEditProject(10000);p.restore(listOf(c),catalog.filterKeys{it!="primary"});val request=VideoBatchReview(p.segments,null);val stage=Any();request.open(stage);request.propose(stage,VideoClipReplacement.propose(p.segments,0,catalog,"other",0));when(mode){0->{request.dismiss(stage);assertFalse(request.apply(stage,p){})};1->assertFalse(request.apply(Any(),p){});2->assertThrows(IllegalStateException::class.java){request.apply(stage,p){error("paused")}};3->{p.setTitle(0,"Changed");assertThrows(IllegalArgumentException::class.java){request.apply(stage,p){}}}};assertEquals("primary",p.segments.single().sourceId);assertEquals(c.captions,p.segments.single().captions)}}
}
